  "请选择源图层": "Elige la capa de origen",
  "减淡/加深中点要在 0.05–0.95 之间（0.5 = 无效果）⇒ 未建组，没有发送请求、没有写入任何改动。": "Los puntos medios de sobre/subexposición deben estar entre 0,05 y 0,95 (0,5 = sin efecto) ⇒ grupo no creado: no se envió petición ni se escribió ningún cambio.",
  "未建组：本地内核没有 dodge_burn_setup 这个端点（这次请求没到服务端）⇒ 勾回「服务器渲染」再试。": "Grupo no creado: el núcleo local no tiene el punto de acceso dodge_burn_setup (la petición nunca llegó al servidor) ⇒ vuelve a marcar «Renderizar en el servidor» e inténtalo de nuevo.",
  "⚠ 组建好了，但服务端回执 effective=false ⇒ 这一臂不会改变画面（完整原因见下方日志）。": "⚠ El grupo se creó, pero el recibo del servidor dice effective=false ⇒ esta vía no cambiará la imagen (el motivo completo está en el registro de abajo).",
  "区域填充": "Relleno de región",
  "往一块形状里填色或铺纹理。落的是「一个形状对象」，不是一次性烘焙：之后还能选中它改羽化与不透明度。": "Rellena una forma con un color o una textura. Lo que se deposita es un único objeto de forma, no un mapa de bits horneado: podrás seleccionarlo después y seguir cambiando su borde suave y su opacidad.",
