  "那一层不在服务端的图层清单里（可能刚被删）⇒ 未填充。": "Esa capa no está en la lista de capas del servidor (puede que acabe de borrarse) ⇒ no rellenado.",
  "不透明度要在 0 到 1 之间 ⇒ 未填充，没有发送请求、没有写入任何改动。": "La opacidad debe estar entre 0 y 1 ⇒ no rellenado: no se envió petición ni se escribió ningún cambio.",
  "羽化半径不能是负数 ⇒ 未填充。": "El radio del borde suave no puede ser negativo ⇒ no rellenado.",
