  "路径要写 `d`（SVG 路径字符串，M/L/C/Q/H/V/Z）⇒ 未填充。": "Una ruta necesita su `d` (una cadena de ruta SVG, M/L/C/Q/H/V/Z) ⇒ no rellenado.",
  "取纹理那块矩形的宽高都要大于 0 ⇒ 未填充。": "El ancho y el alto del rectángulo de textura deben ser mayores que 0 ⇒ no rellenado.",
  "未填充：本地内核没有这个端点（这次请求没到服务端）⇒ 勾回「服务器渲染」再试。": "No rellenado: el núcleo local no tiene ese punto de acceso (la petición nunca llegó al servidor) ⇒ vuelve a marcar «Renderizar en el servidor» e inténtalo de nuevo.",
  "未填充：服务端拒绝了这次落笔（原因见下方日志）。它拒绝时不写原子 ⇒ 不会留下半个形状。": "No rellenado: el servidor rechazó este trazo (el motivo está en el registro de abajo). Cuando rechaza no escribe ningún átomo ⇒ no queda ninguna forma a medias.",
