  "落笔：形状尺寸不合法时不发送请求、不写入任何改动": "Depositar el trazo: si el tamaño de la forma no es válido no se envía petición ni se escribe ningún cambio",
  "「取画面这块」取的是此刻那块矩形的像素（服务端就地存成纹理），不是实时链接：先把那块画好再指它。羽化只作用于边缘的不透明度。": "«Textura de parche» lee los píxeles de ese rectángulo tal como están ahora mismo (el servidor los guarda al momento como textura): no es un enlace vivo; pinta primero ese trozo y luego apúntalo. El borde suave solo afecta a la opacidad a lo largo del borde.",
  "矩形蒙版": "Máscara rectangular",
