  "把勾选的对象上移一层（reorder_objects，一次只动一个对象）": "Sube el objeto marcado un nivel (reorder_objects; un objeto cada vez)",
  "把勾选的对象下移一层（reorder_objects，一次只动一个对象）": "Baja el objeto marcado un nivel (reorder_objects; un objeto cada vez)",
  "纵轴按对数画：平涂文档里那几笔颜色的桶只有几十个像素，线性轴下会被压成看不见（数值本身仍是服务端给的 ✓）": "El eje vertical es logarítmico: en un documento pintado en plano las clases de color contienen solo decenas de píxeles y un eje lineal las aplastaría fuera de la vista (los números en sí vienen directos del servidor ✓)",
  "写一个命名锚点（set_anchor）；同名再设 = 覆盖，不必先删": "Escribe un ancla con nombre (set_anchor); fijar el mismo nombre otra vez simplemente sobrescribe, no hace falta borrar antes",
