  "把这套预设落到当前图层（apply_preset）；强度与旋钮按上面的值": "Aplica este preajuste a la capa actual (apply_preset); la intensidad y los controles usan los valores de arriba",
  "把这条锚点的名字与坐标填回上面的框（改坐标时不必重新目测 ✓）": "Devuelve el nombre y las coordenadas de esta ancla a las casillas de arriba (para ajustar una coordenada sin volver a estimar a ojo ✓)",
  "删掉这个锚点（delete_anchor；不存在会报错，不会静默成功 ✓）": "Borra esta ancla (delete_anchor; una ancla que no existe es un error, nunca un éxito silencioso ✓)",
  "留空 ⇒ 整幅；填齐 x,y,w,h 才生效": "Dejar vacío ⇒ lienzo completo; deben rellenarse los cuatro x, y, an, al para que surta efecto",
  "取样档位：lod:k ⇒ 输出尺寸 = 区域 ÷ 2^k（向上取整），不经过全分辨率中间缓冲": "Nivel de muestreo: lod:k ⇒ tamaño de salida = región ÷ 2^k (redondeado hacia arriba), sin pasar por el búfer intermedio de resolución completa",
  "用当前选区的包围盒填充区域四个框（选区来自服务端事实）": "Rellena las cuatro casillas de región con el marco de la selección actual (la selección viene de los hechos del servidor)",
  "只导当前图层（隐藏层也照导——导出某一层是明确要求）": "Exporta solo la capa actual (las capas ocultas también se exportan: exportar una capa con nombre es una petición explícita)",
  "服务端渲染（可只导一个区域、可降档取样、可按尺寸缩放），结果直接下载到本机（export_png）": "Renderización en el servidor (una sola región, submuestreada por nivel o escalada a un tamaño); el resultado se descarga directo a esta máquina (export_png)",
  "文本字体：内置点阵走服务端位图图集；其余走浏览器 Canvas 渲染系统字体（支持中文、emoji、任意字号）": "Fuente de texto: la de mapa de bits integrada usa el atlas de glifos del servidor; las demás renderizan fuentes del sistema con el lienzo del navegador (chino, emoji y cualquier tamaño)",
  "导出成分层 PSD（图层/组/不透明度/可见性/混合模式都带出去）": "Exportar como PSD con capas (incluye capas, grupos, opacidad, visibilidad y modos de fusión)",
  "查看选中对象的版本历史（原子版本链）": "Muestra el historial de versiones del objeto seleccionado (su cadena de versiones de átomos)",
  "用笔触自动生成渐变过渡（替代手动拼笔）": "Genera una transición de degradado a partir de trazos de pincel en vez de puntearla a mano",
  "笔刷压感动力学（MCP set_brush_dynamics 的 Web 入口）：压感→笔触大小的响应曲线": "Dinámica de presión del pincel (la entrada web del set_brush_dynamics de MCP): la curva de respuesta presión → tamaño del trazo",
  "轻压细、重压粗（柔和）": "Presión ligera fina, presión fuerte gruesa (suave)",
  "线性响应": "Respuesta lineal",
  "轻压粗、重压变化小（硬）": "Presión ligera gruesa, poco cambio con presión fuerte (dura)",
  "文件：新建 / 打开 / 导入 / 导出（顶栏这一个入口，信息面板里不再重复）": "Archivo: nuevo / abrir / importar / exportar; esta única entrada vive en la barra superior y no se repite en el panel de información",
  "隐藏 / 显示左侧工具栏（快捷键 [ ）": "Ocultar / mostrar la barra de herramientas izquierda (atajo [ )",
