  "「取画面这块」烤的是此刻那块的像素，不跟随后续修改。": "«Textura de recorte» assa os pixels daquele retângulo como estão agora — não acompanha alterações posteriores.",
  "那一层不在服务端的图层清单里（可能刚被删）⇒ 未填充。": "Essa camada não está na lista de camadas do servidor (pode ter acabado de ser excluída) ⇒ não preenchido.",
  "不透明度要在 0 到 1 之间 ⇒ 未填充，没有发送请求、没有写入任何改动。": "A opacidade deve estar entre 0 e 1 ⇒ não preenchido: nenhuma requisição enviada e nenhuma alteração escrita.",
  "羽化半径不能是负数 ⇒ 未填充。": "O raio da borda suave não pode ser negativo ⇒ não preenchido.",
  "形状的尺寸要大于 0 ⇒ 未填充，没有发送请求、没有写入任何改动。": "O tamanho da forma deve ser maior que 0 ⇒ não preenchido: nenhuma requisição enviada e nenhuma alteração escrita.",
  "椭圆的两个半径都要大于 0 ⇒ 未填充。": "Os dois raios da elipse devem ser maiores que 0 ⇒ não preenchido.",
  "折线至少要 3 个顶点（形如 `x,y`，空格或分号分隔）⇒ 未填充。": "Um polígono precisa de pelo menos 3 vértices (escritos como `x,y`, separados por espaços ou ponto e vírgula) ⇒ não preenchido.",
  "路径要写 `d`（SVG 路径字符串，M/L/C/Q/H/V/Z）⇒ 未填充。": "Um caminho precisa do seu `d` (uma string de caminho SVG, M/L/C/Q/H/V/Z) ⇒ não preenchido.",
  "取纹理那块矩形的宽高都要大于 0 ⇒ 未填充。": "A largura e a altura do retângulo de textura devem ser maiores que 0 ⇒ não preenchido.",
  "未填充：本地内核没有这个端点（这次请求没到服务端）⇒ 勾回「服务器渲染」再试。": "Não preenchido: o núcleo local não tem esse endpoint (a requisição nunca chegou ao servidor) ⇒ marque de novo «Renderizar no servidor» e tente outra vez.",
  "未填充：服务端拒绝了这次落笔（原因见下方日志）。它拒绝时不写原子 ⇒ 不会留下半个形状。": "Não preenchido: o servidor rejeitou este traço (o motivo está no registro abaixo). Quando recusa, ele não escreve átomo nenhum ⇒ não fica forma pela metade.",
  "该点不在画布内 ⇒ 没有实测读数": "Esse ponto está fora da tela ⇒ não há leitura medida",
  "当前没有可用选区 ⇒ 先用选区工具拖一块（外框来自服务端事实，不是本地猜测）": "Não há seleção para ler ⇒ arraste primeiro uma com a ferramenta de seleção (a moldura dela vem dos fatos do servidor, não de um palpite local)",
