  "落笔：形状尺寸不合法时不发送请求、不写入任何改动": "Depositar o traço: se o tamanho da forma for inválido, nenhuma requisição é enviada e nenhuma alteração é escrita",
  "「取画面这块」取的是此刻那块矩形的像素（服务端就地存成纹理），不是实时链接：先把那块画好再指它。羽化只作用于边缘的不透明度。": "«Textura de recorte» lê os pixels daquele retângulo como estão neste exato momento (o servidor os guarda na hora como textura) — não é um vínculo vivo: pinte primeiro aquele pedaço e depois aponte para ele. A borda suave afeta apenas a opacidade ao longo da borda.",
