  "支持浏览器能解码的任何格式（PNG/JPEG/WebP）。图片在新图层上按原始像素导入。": "ブラウザがデコードできる形式なら何でも（PNG/JPEG/WebP）。画像は元のピクセルのまま新しいレイヤーに来ます",
