  "勾选对象后可「实例化」「编组」「变换」（实例与 master 联动，设计 9.1）。「重采样」只作用于光栅对象（导入的图片、PSD 合成图）——手画的笔迹是 stroke，服务端会明确拒绝并告知类型（先用「转为形状」或改为导入图片）。": "オブジェクトにチェックすると「インスタンス化」「グループ化」「変形」ができます（インスタンスはマスターに連動します。設計 9.1）。「リサンプリング」はラスターオブジェクト（インポートした画像、PSD 合成画像）にだけ作用します — 手描きの筆跡は stroke で、サーバーは型を明示して明確に拒否します（先に「形状に変換」するか、画像としてインポートしてください）。",
  "另一个 AI 用本应用的 MCP 工具所画；参照 Met／NGA 的公有领域德加原作，只用来看风格：没有导入任何原作位图，每个像素都是笔刷/介质笔触。": "別の AI がこのアプリの MCP ツールで描いたもの。Met／NGA のパブリックドメインのドガ原作を参照し、スタイルを見るためだけに使います：原作のビットマップは一切インポートしておらず、すべてのピクセルはブラシ／画材のストロークです。",
