const I18N_JA_ATTR_PATTERNS = [
  [/^(.*)（点击选中 ✓）$/, (m) => m[1] + "（クリックで選択 ✓）"],
  [/^(.*) ⇒ 缩略图没发出来（`\/textures\/` 路由或资产目录有问题 ✓）$/,
    (m) => m[1] + " ⇒ サムネイルが届きませんでした（`/textures/` ルートまたはアセットディレクトリに問題があります ✓）"],
  [/^(.*)（点击取色 ✓）$/, (m) => m[1] + "（クリックでこの色を取る ✓）"],
  [/^(.*) 预览$/, (m) => m[1] + " プレビュー"],
  [/^离线时改动先写进浏览器本地队列，联网后按顺序补交；服务端上的这份文档若已变化则暂停补交（上限 (\d+) 条 \/ (\d+) MB）(。其他文档还有 (\d+) 条未补交)?$/,
    (m) => "オフライン時の変更はまずこのブラウザのキューに入り、オンラインに戻ると順番に再送されます。" +
      "サーバー側のこのドキュメントが変わっていた場合、再送は一時停止します（上限 " + m[1] +
      " 件 / " + m[2] + " MB）" +
      (m[4] ? "。他のドキュメントにあと " + m[4] + " 件の未再送があります" : "")],
];

