  "分离": "Разделить",
  "请选择要分离的图层": "Выберите слой для разделения",
  "该层没有对象 ⇒ 服务端会直接拒绝（没有可分离的像素）": "В этом слое нет объектов ⇒ сервер откажет сразу (разделять нечего: нет пикселей)",
  "高频层的中性灰是 188（不是 Photoshop 式的 128）：在「高频绘画」层上涂抹要用 188 作中性色，用 128 会压暗。源图层保持可见，新组盖在它上面；要整组撤掉请用「历史（原子日志）」卡逐条回退。": "Нейтральный серый слоя высоких частот — 188 (не photoshop-овские 128): рисуя на слое «Рисование по высоким», используйте 188 как нейтральный — 128 затемняет. Исходный слой остаётся видимым, новая группа лежит поверх него; чтобы убрать всю группу, откатывайте записи по одной в карточке «История (журнал атомов)».",
  "半径要在 1–64 之间（高斯 sigma）⇒ 未分离，没有发送请求、没有写入任何改动。": "Радиус должен быть между 1 и 64 (гауссова сигма) ⇒ не разделено: запрос не отправлен и никаких изменений не записано.",
  "那一层不在服务端的图层清单里（可能刚被删）⇒ 未分离。": "Того слоя нет в списке слоёв сервера (возможно, его только что удалили) ⇒ не разделено.",
  "未分离：本地内核没有这个端点（这次请求没到服务端）⇒ 勾回「服务器渲染」再试。": "Не разделено: у локального ядра нет такой конечной точки (запрос так и не дошёл до сервера) ⇒ снова отметьте «Рендеринг на сервере» и повторите.",
  "未分离：服务端拒绝了这次分离（原因见下方日志）。它拒绝时不建组 ⇒ 不会留下半套层。": "Не разделено: сервер отклонил это разделение (причина — в журнале ниже). При отказе группа не строится ⇒ недоделанных слоёв не остаётся.",
  "减淡加深": "Осветление / затемнение",
  "给一块区域做减淡（提亮）与加深（压暗）。": "Осветляет (dodge) и затемняет (burn) область.",
