  "建组": "Построить группу",
  "灰层法的中性字节由服务端回执给出（本引擎是 188，不是 128）。": "Нейтральный байт серого слоя приходит из ответа сервера (в этом движке 188, а не 128).",
  "请选择源图层": "Выберите исходный слой",
  "减淡/加深中点要在 0.05–0.95 之间（0.5 = 无效果）⇒ 未建组，没有发送请求、没有写入任何改动。": "Средние точки осветления/затемнения должны быть между 0,05 и 0,95 (0,5 = без эффекта) ⇒ группа не построена: запрос не отправлен и никаких изменений не записано.",
  "未建组：本地内核没有 dodge_burn_setup 这个端点（这次请求没到服务端）⇒ 勾回「服务器渲染」再试。": "Группа не построена: у локального ядра нет конечной точки dodge_burn_setup (запрос так и не дошёл до сервера) ⇒ снова отметьте «Рендеринг на сервере» и повторите.",
  "⚠ 组建好了，但服务端回执 effective=false ⇒ 这一臂不会改变画面（完整原因见下方日志）。": "⚠ Группа построена, но ответ сервера говорит effective=false ⇒ этот путь картинку не изменит (полная причина — в журнале ниже).",
  "区域填充": "Заливка области",
