  "「取画面这块」烤的是此刻那块的像素，不跟随后续修改。": "«Текстура из участка» запекает пиксели того прямоугольника как они есть сейчас — она не следует за позднейшими правками.",
  "那一层不在服务端的图层清单里（可能刚被删）⇒ 未填充。": "Того слоя нет в списке слоёв сервера (возможно, его только что удалили) ⇒ не залито.",
  "不透明度要在 0 到 1 之间 ⇒ 未填充，没有发送请求、没有写入任何改动。": "Непрозрачность должна быть между 0 и 1 ⇒ не залито: запрос не отправлен и никаких изменений не записано.",
  "羽化半径不能是负数 ⇒ 未填充。": "Радиус мягкого края не может быть отрицательным ⇒ не залито.",
  "形状的尺寸要大于 0 ⇒ 未填充，没有发送请求、没有写入任何改动。": "Размер формы должен быть больше 0 ⇒ не залито: запрос не отправлен и никаких изменений не записано.",
  "椭圆的两个半径都要大于 0 ⇒ 未填充。": "Оба радиуса эллипса должны быть больше 0 ⇒ не залито.",
  "折线至少要 3 个顶点（形如 `x,y`，空格或分号分隔）⇒ 未填充。": "Многоугольнику нужно не меньше 3 вершин (записываются как `x,y`, через пробел или точку с запятой) ⇒ не залито.",
  "路径要写 `d`（SVG 路径字符串，M/L/C/Q/H/V/Z）⇒ 未填充。": "Пути нужен его `d` (строка пути SVG, M/L/C/Q/H/V/Z) ⇒ не залито.",
  "取纹理那块矩形的宽高都要大于 0 ⇒ 未填充。": "Ширина и высота прямоугольника текстуры должны быть больше 0 ⇒ не залито.",
  "未填充：本地内核没有这个端点（这次请求没到服务端）⇒ 勾回「服务器渲染」再试。": "Не залито: у локального ядра нет такой конечной точки (запрос так и не дошёл до сервера) ⇒ снова отметьте «Рендеринг на сервере» и повторите.",
  "未填充：服务端拒绝了这次落笔（原因见下方日志）。它拒绝时不写原子 ⇒ 不会留下半个形状。": "Не залито: сервер отклонил этот мазок (причина — в журнале ниже). При отказе атом не пишется ⇒ недоделанных форм не остаётся.",
