  "源宽": "Quellbreite",
  "源高": "Quellhöhe",
  "「取画面这块」烤的是此刻那块的像素，不跟随后续修改。": "«Ausschnitt-Textur» brennt die Pixel dieses Rechtecks ein, wie sie jetzt sind — sie folgt späteren Änderungen nicht.",
  "那一层不在服务端的图层清单里（可能刚被删）⇒ 未填充。": "Diese Ebene steht nicht in der Ebenenliste des Servers (sie wurde vielleicht gerade gelöscht) ⇒ nicht gefüllt.",
  "不透明度要在 0 到 1 之间 ⇒ 未填充，没有发送请求、没有写入任何改动。": "Die Deckkraft muss zwischen 0 und 1 liegen ⇒ nicht gefüllt: keine Anfrage gesendet und keine Änderung geschrieben.",
  "羽化半径不能是负数 ⇒ 未填充。": "Der Radius der weichen Kante darf nicht negativ sein ⇒ nicht gefüllt.",
  "形状的尺寸要大于 0 ⇒ 未填充，没有发送请求、没有写入任何改动。": "Die Formgröße muss über 0 liegen ⇒ nicht gefüllt: keine Anfrage gesendet und keine Änderung geschrieben.",
  "椭圆的两个半径都要大于 0 ⇒ 未填充。": "Beide Radien der Ellipse müssen über 0 liegen ⇒ nicht gefüllt.",
  "折线至少要 3 个顶点（形如 `x,y`，空格或分号分隔）⇒ 未填充。": "Ein Vieleck braucht mindestens 3 Eckpunkte (geschrieben als `x,y`, durch Leerzeichen oder Semikolon getrennt) ⇒ nicht gefüllt.",
  "路径要写 `d`（SVG 路径字符串，M/L/C/Q/H/V/Z）⇒ 未填充。": "Ein Pfad braucht sein `d` (eine SVG-Pfadzeichenkette, M/L/C/Q/H/V/Z) ⇒ nicht gefüllt.",
  "取纹理那块矩形的宽高都要大于 0 ⇒ 未填充。": "Breite und Höhe des Texturrechtecks müssen beide über 0 liegen ⇒ nicht gefüllt.",
  "未填充：本地内核没有这个端点（这次请求没到服务端）⇒ 勾回「服务器渲染」再试。": "Nicht gefüllt: der lokale Kern hat diesen Endpunkt nicht (die Anfrage erreichte den Server nie) ⇒ setzen Sie «Auf dem Server rendern» wieder und versuchen Sie es erneut.",
  "未填充：服务端拒绝了这次落笔（原因见下方日志）。它拒绝时不写原子 ⇒ 不会留下半个形状。": "Nicht gefüllt: der Server hat diesen Strich abgelehnt (Grund im Protokoll unten). Beim Ablehnen schreibt er kein Atom ⇒ es bleibt keine halbfertige Form zurück.",
  "该点不在画布内 ⇒ 没有实测读数": "Der Punkt liegt außerhalb der Leinwand ⇒ kein Messwert",
  "当前没有可用选区 ⇒ 先用选区工具拖一块（外框来自服务端事实，不是本地猜测）": "Es gibt keine Auswahl zum Lesen ⇒ ziehen Sie zuerst eine mit dem Auswahlwerkzeug (ihr Rahmen kommt aus den Fakten des Servers, nicht aus einer lokalen Vermutung)",
  "已按设置跳过（用服务端渲染）": "Durch Einstellung übersprungen (Server-Rendering)",
  "已清除参考图": "Referenz gelöscht",
  "参考图由外部设置，本浏览器没有它的原图（存储里是裸像素）⇒ 重新上传一次就能一直显示": "Die Referenz wurde von außen gesetzt; dieser Browser hat kein Original von ihr (im Speicher liegen rohe Pixel) ⇒ laden Sie sie noch einmal hoch, dann bleibt sie sichtbar",
  "参考图已就位（从服务端读取原图）": "Referenzbild bereit (Original vom Server gelesen)",
  "正在上传参考图…": "Referenzbild wird hochgeladen…",
  "参考图叠不上去：存储里那份是裸像素（本浏览器没有它的原图）⇒ 已收起画布上的这一层，重新上传一次就能一直显示": "Die Referenz lässt sich nicht überlagern: die gespeicherte Kopie sind rohe Pixel (dieser Browser hat kein Original) ⇒ diese Schicht auf der Leinwand ist eingeklappt; laden Sie sie noch einmal hoch, dann bleibt sie sichtbar",
