  "问题反馈、协作沟通、缺陷上报：": "Rückmeldungen, Zusammenarbeit und Fehlerberichte:",
  "安全漏洞请勿开公开 issue，直接发邮件。": "Öffnen Sie für ein Sicherheitsproblem bitte kein öffentliches Issue; senden Sie stattdessen eine E-Mail.",
  "用工具栏的「标注」在画布上点一下就新建 ✓；点图钉可选中 ✓。": "Klicken Sie mit dem Werkzeug «Anmerkungen» einmal auf die Leinwand, um eine zu erstellen, und klicken Sie auf eine Nadel, um sie auszuwählen ✓.",
