  "回执说成功了，但效果清单里没把它读回来 ⇒ 现在没法说它存成了什么参数（刷新页面再看，或看下方日志）。": "Die Antwort sagt, es habe geklappt, aber die Effektliste hat es nicht zurückgelesen ⇒ es gibt nichts Ehrliches über die gespeicherten Parameter zu sagen (laden Sie die Seite neu oder sehen Sie ins Protokoll unten).",
